// Documents — Codex index view models against the prototype's own render values (docs.golden.json, generated by
// scripts/proto-golden-docs.ts from design lines 3096–5239, renderValsEN and renderVals in French) on the seeded
// in-memory database, in EN and FR: KPI tiles, scope / views / family / status chips, vault rows and filters, the
// document record drawer, the deposit hand-off, the Document types register and the template labels. Deliberate
// deviations (see the comments) are asserted explicitly.
import { beforeAll, describe, expect, it, vi } from 'vitest';
vi.mock('next/navigation', () => ({
  usePathname: () => '/projects/HLT-026/documents',
  useRouter: () => ({ push() {}, replace() {}, refresh() {} }),
  useSearchParams: () => new URLSearchParams(),
}));
vi.mock('./actions', () => ({ depositInCodexAction: vi.fn(), approveDocumentAction: vi.fn(), logDownloadAction: vi.fn(), syncCodexAction: vi.fn() }));

import { createElement, type ComponentProps, type ReactElement } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { I18nProvider } from '@/i18n/client';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { DEPOSIT_TYPES } from '@/server/db/codes';
import { openDatabase } from '@/server/db/open';
import { getCodexSyncState, getDocumentRecord, listDocumentTypes, listVaultDocuments } from '@/server/dal/documents';
import { docsBadge } from '@/server/dal/docs-badge';
import GOLD from './docs.golden.json';
import { depositHref, docHref, documentsHref } from './links';
import { depositView, docTypesView, drawerView, vaultView, type DocsState } from './model';
import { DocsVault } from './vault';
import { DocTypesRegister } from './doc-types';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLD as any;
const LANGS: Lang[] = ['en', 'fr'];
const S0: DocsState = { scope: 'proj', view: 'all', family: null, status: null, q: '', doc: null };
const DIRECTOR = { short: 'M. Lefebvre', role: 'director' };
/** Labels the prototype dictionary leaves in English, translated in src/i18n/extra/docs.json. */
const FR_GAPS: Record<string, string> = { 'PLC variable table': 'Table de variables automate' };
const frGap = (lang: Lang, s: string) => (lang === 'fr' && Object.hasOwn(FR_GAPS, s) ? FR_GAPS[s] : s);
/**
 * R-148 (NEW-D1-2): the keywords of a Codex record are shown as typed — their exact French entry or the stored text, never
 * the prototype's segment translation ("CR-RAIL-A100 · heat 7712" was shown as "… · coulée 7712").
 */
const tagsAsTyped = (lang: Lang, s: string) => (lang === 'fr' ? s.replace(/coulée (\d+)/g, 'heat $1') : s);
const withI18n = (lang: Lang, el: ReactElement) => createElement(I18nProvider, { lang } as ComponentProps<typeof I18nProvider>, el);

beforeAll(async () => {
  setDb(await openDatabase());
}, 60_000);

async function vault(lang: Lang, state: Partial<DocsState> = {}, project = 'HLT-026') {
  const [docs, sync] = await Promise.all([listVaultDocuments(), getCodexSyncState()]);
  return vaultView({ project, docs, sync, state: { ...S0, ...state } }, makeT(lang), lang);
}
const chips = (xs: { label: string; count: number }[]) => xs.map((x) => ({ label: x.label, count: String(x.count) }));
const ids = (v: Awaited<ReturnType<typeof vault>>) => v.rows.map((r) => r.number);

describe('vault (dvKpis, dvScope, dvViews, dvFam, dvSt, dvList) — EN and FR', () => {
  it.each(LANGS)('%s: KPI tiles, chips, count and sync line for HLT-026, all projects, NDC-031 and EWA-051', async (lang) => {
    const cases = [
      [{}, 'HLT-026', G[lang].hlt],
      [{ scope: 'all' as const }, 'HLT-026', G[lang].all],
      [{}, 'NDC-031', G[lang].ndc],
      [{}, 'EWA-051', G[lang].ewa],
    ] as const;
    for (const [state, project, g] of cases) {
      const v = await vault(lang, state, project);
      expect(v.kpis.map((k) => ({ label: k.label, value: Number(k.value), sub: k.sub, color: k.color })), project).toEqual(g.kpis);
      expect(v.scope.options.map((o) => o.label)).toEqual(g.scope);
      expect(chips(v.views.chips)).toEqual(g.views.map((c: any) => ({ label: c.label, count: c.count })));
      expect(chips(v.families.chips)).toEqual(g.fam.map((c: any) => ({ label: c.label, count: c.count })));
      expect(chips(v.statuses.chips)).toEqual(g.st.map((c: any) => ({ label: c.label, count: c.count })));
      expect(v.title).toBe(`${lang === 'fr' ? 'Coffre-fort' : 'Vault'} · ${g.count}`);
      expect(v.sync).toBe(g.sync);
      expect(v.rows.map((r) => ({
        id: r.number, title: r.title, typeLabel: r.kind, svcLabel: r.service, proj: r.project, rev: r.revision, status: r.status, stClass: r.statusClass,
        conf: r.conf, confClass: r.confClass, tags: r.tags, isNew: r.isNew,
      }))).toEqual(g.list.map((d: any) => ({ ...d, typeLabel: frGap(lang, d.typeLabel), tags: tagsAsTyped(lang, d.tags) })));
    }
  });

  it.each(LANGS)('%s: saved views, family / status filters and search', async (lang) => {
    const g = G[lang];
    for (const view of ['bpe', 'audit', 'client', 'pending', 'obsolete'] as const) {
      expect(ids(await vault(lang, { view })), view).toEqual(g.views[view]);
      expect(ids(await vault(lang, { scope: 'all', view })), view).toEqual(g.allViews[view]);
    }
    expect(ids(await vault(lang, { family: 'quality' }))).toEqual(g.filters.famQuality);
    expect(ids(await vault(lang, { status: 'draft' }))).toEqual(g.filters.stDraft);
    expect(ids(await vault(lang, { view: 'audit', family: 'purchasing' }))).toEqual(g.filters.auditPurchasing);
    expect(ids(await vault(lang, { q: 'nordvolt' }))).toEqual(g.filters.qNordvolt);
    expect(ids(await vault(lang, { q: 'g. comte' }))).toEqual(g.filters.qComte);
    expect(ids(await vault(lang, { q: 'material certificate' }))).toEqual(g.filters.qCertificate);
    const none = await vault(lang, { q: 'zzz' });
    expect(none.title.endsWith(g.filters.noMatch)).toBe(true);
    expect(none.empty).toBe(lang === 'fr' ? 'Aucun document ne correspond' : 'No document matches');
  });

  it('FR search also matches what the viewer reads (French title and kind)', async () => {
    expect(ids(await vault('fr', { q: 'épaisseur' }))).toEqual(['NCR-HLT-031']);
    expect(ids(await vault('fr', { q: 'certificat matière' }))).toEqual(['CER-HLT-039', 'CER-HLT-040']);
    expect(ids(await vault('en', { q: 'épaisseur' }))).toEqual([]);
  });

  it('links keep the vault state; a view chip clears family and status; a row toggles the drawer', async () => {
    const v = await vault('en', { scope: 'all', family: 'quality', status: 'released', q: 'iso', doc: 'PRO-QMS-001' });
    expect(v.scope.options[0].href).toBe('/projects/HLT-026/documents?fam=quality&status=released&q=iso&doc=PRO-QMS-001'.replace('&doc=PRO-QMS-001', ''));
    expect(v.views.chips[2].href).toBe('/projects/HLT-026/documents?scope=all&view=audit&q=iso');
    expect(v.families.chips[0].href).toBe('/projects/HLT-026/documents?scope=all&status=released&q=iso');
    const pro = v.rows.find((r) => r.number === 'PRO-QMS-001')!;
    expect([pro.open, pro.href]).toEqual([true, '/projects/HLT-026/documents?scope=all&fam=quality&status=released&q=iso']);
    const other = v.rows.find((r) => r.number !== 'PRO-QMS-001')!;
    expect(other.href).toBe(`/projects/HLT-026/documents?scope=all&fam=quality&status=released&q=iso&doc=${other.number}`);
  });

  it('URL helpers for other screens', () => {
    expect(documentsHref('HLT-026')).toBe('/projects/HLT-026/documents');
    expect(docHref('MIN-HLT-023', 'HLT-026')).toBe('/projects/HLT-026/documents?doc=MIN-HLT-023');
    expect(depositHref('HLT-026', { type: 'CER', part: 'CR-RAIL-A100' })).toBe('/projects/HLT-026/documents?deposit=new&dtype=CER&part=CR-RAIL-A100');
    expect(depositHref('HLT-026', { revisionOf: 'PID-HLT-026' }, { scope: 'all', doc: 'PID-HLT-026' })).toBe('/projects/HLT-026/documents?scope=all&deposit=PID-HLT-026');
  });

  it('sidebar badge: records awaiting approval, all projects', async () => {
    expect(await docsBadge()).toBe('1');
  });

  it('static render: banner, KPI tiles, filters and the vault table (FR)', async () => {
    const t = makeT('fr');
    const v = await vault('fr', { view: 'pending' });
    const html = renderToStaticMarkup(
      withI18n('fr', createElement(DocsVault, { project: 'HLT-026', view: v, canEdit: true, openToast: 'x', t })),
    );
    for (const s of ['Les documents projet vivent dans Codex', 'Dernière synchro 08:02 · 412 fiches', 'Synchroniser', 'Ouvrir Codex', 'Documents dans le périmètre',
      'Vues enregistrées', 'En attente d’approbation', 'Rechercher numéro, titre, tag, auteur…', 'Toutes familles', 'Tous statuts', 'Coffre-fort · 1 / 40 documents',
      'RPT-HLT-014', 'Rapport d’alignement des rails de grue', 'Diffusion proposée', 'Exporter le registre (xlsx)', 'Sélectionner RPT-HLT-014'])
      expect(html, s).toContain(s);
    expect(v.rows[0].href).toBe('/projects/HLT-026/documents?view=pending&doc=RPT-HLT-014');
    expect(html).not.toContain('Aucun document ne correspond');
    const ro = renderToStaticMarkup(
      withI18n('en', createElement(DocsVault, { project: 'HLT-026', view: await vault('en'), canEdit: false, openToast: 'x', t: makeT('en') })),
    );
    expect(ro).not.toContain('Sync now');
    expect(ro).toContain('Open Codex');
  });
});

// ── Drawer ─────────────────────────────────────────────────────────────────────────────────────────────

async function drawer(lang: Lang, number: string, viewer = DIRECTOR, canEdit = true, state: Partial<DocsState> = {}) {
  const record = (await getDocumentRecord(number))!;
  return drawerView({ project: 'HLT-026', record, state: { ...S0, scope: 'all', doc: number, ...state }, viewer, canEdit }, makeT(lang), lang);
}

/** French deliberate fixes: "Type" value and approval circuit roles are translated ("Direction" is not "Sens"). */
function expectedMeta(lang: Lang, g: any, record: { typeLabel: string; type: string }) {
  if (lang === 'en') return g.meta;
  const t = makeT('fr');
  return g.meta.map((m: any) =>
    m.k === 'Type' ? { k: m.k, v: `${t(record.typeLabel)} (${record.type})` } : m.k === 'Circuit d’approbation' ? { k: m.k, v: m.v.replace('Sens', 'Direction') } : m,
  );
}

describe('document record drawer (showDoc, docVals) — EN and FR', () => {
  it.each(LANGS)('%s: header, identity, classification, revisions, approval proof, distribution, download log, relations', async (lang) => {
    for (const [number, g] of Object.entries(G[lang].drawers) as [string, any][]) {
      const d = await drawer(lang, number);
      const record = (await getDocumentRecord(number))!;
      expect(d.head, number).toBe(`${G.labels['Document record'] && (lang === 'fr' ? G.labels['Document record'] : 'Document record')} · ${g.id} · ${g.revText}`);
      expect([d.title, d.conf, d.confClass, d.status, d.statusClass], number).toEqual([g.title, g.conf, g.confClass, g.status, g.stClass]);
      expect(d.identity, number).toEqual(expectedMeta(lang, g, record));
      expect(d.tags, number).toEqual(g.tagList);
      // Current working version: "{rev}.3" (the prototype printed "A.3" for every revision).
      expect(d.revisions.map((r) => ({ rev: r.revision, note: r.note, sub: r.sub, status: r.status, stClass: r.statusClass })), number).toEqual(
        g.revs.map((r: any, i: number) => ({ rev: r.rev, note: r.note, sub: `${r.date} · ${r.by} · ${i === 0 ? `${r.rev}.3` : r.versions}`, status: r.status, stClass: r.stClass })),
      );
      expect(d.revisions.map((r) => r.current)).toEqual(g.revs.map((r: any) => r.color === 'var(--color-text)'));
      const role = (x: string) => (lang === 'fr' && x === 'Sens' ? 'Direction' : x);
      expect(d.approvals.map((a) => ({ label: a.label, state: a.state, signed: a.signed })), number).toEqual(
        g.appr.map((a: any) => ({ label: `${role(a.role)} · ${a.who}`, state: `${a.state} · ${a.when}`, signed: a.dot === 'var(--color-accent)' })),
      );
      // Client row: the project's own client contact (NDC-031: Infrastructure BU, no Keystone contact).
      const dist = g.dist.map((x: any) => ({
        to: number.endsWith('NDC-031') ? x.to.replace(/Port authority · N\. Bensaïd|Autorité portuaire · N\. Bensaïd/, 'Infrastructure BU') : x.to,
        sub: `· rev ${x.rev} · ${x.date}`, ack: x.ack, ackClass: x.cls,
      }));
      expect(d.distribution, number).toEqual(dist);
      expect(d.downloads, number).toEqual(g.dl);
      // "Punch item" has no French in the prototype dictionary ("Réserve" added).
      expect(d.links.map((l) => ({ kind: l.kind, id: l.ref })), number).toEqual(
        g.links.map((l: any) => ({ kind: lang === 'fr' && l.kind === 'Punch item' ? 'Réserve' : l.kind, id: l.id })),
      );
      expect(d.withdrawal).toBe(g.obsNote ? `${lang === 'fr' ? 'Retrait' : 'Withdrawal'} · ${g.obsNote}` : null);
    }
  });

  it('approve button: named next approver or director; label with the role translated in French', async () => {
    expect((await drawer('en', 'RPT-HLT-014')).approveLabel).toBe(G.en.drawers['RPT-HLT-014'].approveLabel);
    expect((await drawer('fr', 'RPT-HLT-014')).approveLabel).toBe('Approuver dans Codex · Responsable qualité · G. Comte');
    expect((await drawer('en', 'RPT-HLT-014', { short: 'G. Comte', role: 'quality' })).approveLabel).toBe('Approve in Codex · Quality manager · G. Comte');
    expect((await drawer('en', 'RPT-HLT-014', { short: 'R. Aubert', role: 'pm' })).approveLabel).toBeNull();
    // Not awaiting approval: no button (the prototype computed the label but hid the button).
    expect((await drawer('en', 'PID-HLT-026')).approveLabel).toBeNull();
  });

  it('actions and links: open toast, new revision hand-off, relation targets, close keeps the vault state', async () => {
    const d = await drawer('fr', 'REC-HLT-009', DIRECTOR, true, { view: 'audit' });
    expect(d.openToast).toBe('Ouverture de Codex · REC-HLT-009 rév. A');
    expect((await drawer('en', 'REC-HLT-009')).openToast).toBe('Opening Codex · REC-HLT-009 rev A');
    expect(d.newRevisionHref).toBe('/projects/HLT-026/documents?scope=all&view=audit&deposit=REC-HLT-009');
    expect(d.closeHref).toBe('/projects/HLT-026/documents?scope=all&view=audit');
    expect(d.links).toEqual([
      { kind: 'Commande d’achat', ref: 'PO-2026-118', href: null },
      { kind: 'Article', ref: 'EL-VFD-200', href: '/reference/parts?part=EL-VFD-200' },
    ]);
    expect((await drawer('en', 'CTR-HLT-002')).links).toEqual([{ kind: 'Change request', ref: 'CR-004', href: '/projects/HLT-026/changes?cr=CR-004' }]);
    expect((await drawer('fr', 'PHO-HLT-011')).links[0]).toEqual({ kind: 'Réserve', ref: 'P-01', href: null });
    expect((await drawer('en', 'PID-HLT-026', DIRECTOR, false)).newRevisionHref).toBeNull();
  });
});

// ── Deposit ────────────────────────────────────────────────────────────────────────────────────────────

async function deposit(lang: Lang, value: string, context: { type?: string; po?: string; part?: string } = {}, project = 'HLT-026', state: Partial<DocsState> = {}) {
  const [docs, types] = await Promise.all([listVaultDocuments(), listDocumentTypes()]);
  return depositView(
    { project, docs, types, depositTypes: DEPOSIT_TYPES, state: { ...S0, ...state }, deposit: value, context: { type: context.type ?? null, po: context.po ?? null, part: context.part ?? null } },
    makeT(lang),
    lang,
  );
}
const metaOf = (g: any, k: string) => g.meta.find((m: any) => m.k === k)?.v;

describe('"Deposit in Codex" hand-off (depVals) — EN and FR', () => {
  it.each(LANGS)('%s: type chips, summary values and numbers previewed per type', async (lang) => {
    const g = G[lang].deposit;
    const v = (await deposit(lang, 'new'))!;
    expect(v.mode).toBe('new');
    expect(v.types.map((x) => ({ code: x.code, label: x.label }))).toEqual(g.default.types);
    expect(v.initial).toEqual({ type: 'CER', po: '', part: '' });
    const cer = v.types.find((x) => x.code === 'CER')!;
    const k = (en: string, fr: string) => (lang === 'fr' ? fr : en);
    expect([v.projectText, cer.circuit, cer.retention, cer.confidentiality, cer.number]).toEqual([
      metaOf(g.default, k('Project', 'Projet')), metaOf(g.default, k('Approval circuit', 'Circuit d’approbation')), metaOf(g.default, k('Retention', 'Rétention')),
      metaOf(g.default, k('Confidentiality', 'Confidentialité')), g.default.number,
    ]);
    // "Type" value: the label is translated in French too (the prototype left "Material certificate (CER)").
    expect(cer.typeText).toBe(lang === 'fr' ? 'Certificat matière (CER)' : metaOf(g.default, 'Type'));
    // A label that already carries its code keeps it once (the prototype printed "Acceptance minutes (PV) (PV)").
    expect(v.types.find((x) => x.code === 'PV')!.typeText).toBe(lang === 'fr' ? 'Procès-verbal de réception (PV)' : 'Acceptance minutes (PV)');
    expect(v.types.find((x) => x.code === 'RPT')!.number).toBe(g.rptEmpty.number);
    expect((await deposit(lang, 'new', {}, 'NDC-031'))!.types.find((x) => x.code === 'PV')!.number).toBe(g.ndcPv.number);
    expect(g.default.steps).toEqual(lang === 'fr' ? ['Fichier & type', 'Métadonnées', 'Numéro & fiche'] : ['File & type', 'Metadata', 'Number & record']);
  });

  it.each(LANGS)('%s: new revision of a record (ctx) — its type, number, confidentiality and first relation', async (lang) => {
    const g = G[lang].deposit.revision;
    const v = (await deposit(lang, 'PID-HLT-026', {}, 'HLT-026', { scope: 'all', q: 'p&id' }))!;
    expect(v.mode).toBe('revision');
    expect(v.revision).toMatchObject({ number: 'PID-HLT-026', type: 'PID', context: lang === 'fr' ? 'PID-HLT-026 · nouvelle révision E' : g.ctxText });
    expect(v.initial).toEqual({ type: 'PID', po: 'D-016', part: '' });
    expect(v.types).toHaveLength(1);
    const ty = v.types[0];
    expect([ty.number, ty.circuit, ty.retention, ty.confidentiality]).toEqual([
      g.number, metaOf(g, lang === 'fr' ? 'Circuit d’approbation' : 'Approval circuit'), metaOf(g, lang === 'fr' ? 'Rétention' : 'Retention'),
      metaOf(g, lang === 'fr' ? 'Confidentialité' : 'Confidentiality'),
    ]);
    expect(v.closeHref).toBe('/projects/HLT-026/documents?scope=all&q=p%26id');
    expect(G[lang].deposit.revision.detected).toBe(lang === 'fr' ? 'Nouvelle révision d’un document existant' : 'New revision of an existing document');
  });

  it('context from another screen (PLM part drawer: CER + article), unknown record or type', async () => {
    const v = (await deposit('en', 'new', { type: 'CER', part: 'EL-VFD-200' }))!;
    expect(v.initial).toEqual({ type: 'CER', po: '', part: 'EL-VFD-200' });
    expect((await deposit('en', 'new', { type: 'PID' }))!.initial.type).toBe('CER');
    expect((await deposit('en', 'new', { type: 'PHO' }))!.initial.type).toBe('PHO');
    expect(await deposit('en', 'NOPE-000')).toBeNull();
    expect((await deposit('en', 'PRO-QMS-001'))!).toMatchObject({ page: 'HLT-026', project: 'QMS', projectText: 'QMS — transverse' });
  });
});

// ── Document types register ────────────────────────────────────────────────────────────────────────────

describe('document types register (docTypesRows) — EN and FR', () => {
  it.each(LANGS)('%s: rows, "In Codex" counts', async (lang) => {
    const rows = docTypesView(await listDocumentTypes(), makeT(lang), lang);
    expect(rows.map((r) => ({ code: r.code, label: r.label, famLabel: r.family, circuit: r.circuit, retention: r.retention, iso: r.iso, clientText: r.client, count: r.count }))).toEqual(
      G[lang].doctypes.map((r: any) => ({ ...r, label: frGap(lang, r.label), circuit: lang === 'fr' ? r.circuit.replace('Sens', 'Direction') : r.circuit })),
    );
  });

  it('static render with and without "Edit in Codex"', async () => {
    const t = makeT('fr');
    const rows = docTypesView(await listDocumentTypes(), t, 'fr');
    const html = renderToStaticMarkup(withI18n('fr', createElement(DocTypesRegister, { rows, editToast: 'x', t })));
    for (const s of ['Synchronisé depuis Codex', 'Modifier dans Codex', 'Registre des types de documents', 'Circuit d’approbation', 'Livrable client', 'Dans Codex',
      'Auteur → Responsable qualité → Direction', 'Schéma de procédé (PFD)'])
      expect(html, s).toContain(s);
    const ro = renderToStaticMarkup(withI18n('fr', createElement(DocTypesRegister, { rows, editToast: null, t })));
    expect(ro).not.toContain('Modifier dans Codex');
  });
});

describe('template labels (2310–2383)', () => {
  it('every label translates to the prototype French', () => {
    const t = makeT('fr');
    for (const [en, fr] of Object.entries(G.labels as Record<string, string>)) expect(t(en), en).toBe(fr);
  });
});
